    final = f"({R}+{P}*pi/2)*a^3"
    exact_float = float(R) + float(P) * math.pi / 2

# Independent numeric check directly from the definitions (midpoint rule, a = 1)
def F(x, y, z):
    return (x - z, y + z, x - y)

N, M = 400, 200
numeric = 0.0
for i in range(N):
    t = -math.pi / 2 + (i + 0.5) * math.pi / N
    x, y = math.cos(t), math.sin(t)
    top = x
    if top <= 0:
        continue
    dz = top / M
    dt = math.pi / N
    for j in range(M):
        z = (j + 0.5) * dz
        Fx_, Fy_, _ = F(x, y, z)
        numeric += (Fx_ * x + Fy_ * y) * dz * dt

ok = abs(numeric - exact_float) < 1e-3
result = {
    "final_answer": final if ok else "UNSUPPORTED",
    "evidence": {
        "coefficient_of_a3": coef_str,
        "exact_float": round(exact_float, 10),
        "numeric_check": round(numeric, 6),
        "agrees": ok,
        "domain": "t in [-pi/2, pi/2], 0 <= z <= a*cos(t)",
        "normal": "outward radial (cos t, sin t, 0)",
        "dS": "a dt dz",
    },
}
